mapper.select:
    select,
                                                 sw1.warehouse_name as source_warehouse_name,
                                                 sw2.warehouse_name as target_warehouse_name,
                                                 bui.name           as add_user_name
from sts_transfer_storage_info tsi
         left join sts_warehouse sw1 on tsi.source_warehouse_id = sw1.id
         left join sts_warehouse sw2 on tsi.target_warehouse_id = sw2.id
         left join base_user_info bui on tsi.add_user = bui.id


            and tsi.transfer_type = #{transferType}


            and tsi.source_warehouse_id = #{sourceWarehouseId}


            and tsi.target_warehouse_id = #{targetWarehouseId}


            and tsi.start_time >= #{startTime}


            and tsi.end_time <= #{endTime}


            and tsi."status" = #{status}


            and tsi.add_user = #{userId}


            and bui.name like concat('%', #{applicant}, '%')


    order by tsi.add_time desc, tsi.id desc
